    /**
     * Tests creating a new DigitalTwin.
     *
     * @return    DigitalTwin
     */
    public DigitalTwin testCreate() throws Throwable {
    DigitalTwin entity = null;

    LOGGER.info( "DigitalTwinTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a DigitalTwin");

    StringBuilder msg = new StringBuilder( "-- Failed to create a DigitalTwin" );

    try {
        entity = service.createDigitalTwin( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getDigitalTwinId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a DigitalTwin with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

