    /**
     * Tests getting all DigitalTwins.
     *
     * @return    Collection
     */
    public List<DigitalTwin> testGetAll() throws Throwable {
    LOGGER.info( "DigitalTwinTest:testGetAll() - Retrieving Collection of DigitalTwins:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DigitalTwin : " );
    List<DigitalTwin> collection  = null;

    try {
        // call the static get method on the DigitalTwinService
        collection = service.getAllDigitalTwin();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DigitalTwin currEntity  = null;
            Iterator<DigitalTwin> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDigitalTwinId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

